import re

_PATTERN = re.compile(r"^(?:(\d+(?:\.\d+)?)h)?(?:(\d+(?:\.\d+)?)m)?(?:(\d+(?:\.\d+)?)s)?$")


def parse_duration(text):
    """Parse durations like '1h30m', '45s' or '1.5h' into seconds."""
    match = _PATTERN.fullmatch(str(text))
    if not match or not any(match.groups()):
        raise ValueError(f"invalid duration: {text!r}")
    hours, minutes, seconds = (float(g) if g else 0 for g in match.groups())
    result = hours * 3600 + minutes * 60 + seconds
    return int(result) if result == int(result) else result


def format_duration(seconds):
    """Format whole seconds back into the shortest string parse_duration accepts."""
    seconds = int(seconds)
    if seconds < 0:
        raise ValueError(f"invalid duration: {seconds!r}")
    hours, rem = divmod(seconds, 3600)
    minutes, secs = divmod(rem, 60)
    if hours and minutes and secs:
        return f"{hours}h{minutes}m{secs}s"
    if hours and minutes:
        return f"{hours}h{minutes}m"
    if hours and secs:
        return f"{hours}h{secs}s"
    if hours:
        return f"{hours}h"
    if minutes and secs:
        return f"{minutes}m{secs}s"
    if minutes:
        return f"{minutes}m"
    return f"{secs}s"

